function maxArea(height: number[]): number {
  let left = 0, right = height.length - 1, best = 0;
  while (left < right) {
    best = Math.max(best, (right - left) * Math.min(height[left], height[right]));
    // 短边不变时缩小宽度不可能改进答案
    if (height[left] < height[right]) left++;
    else right--;
  }
  return best;
}

def maxArea(height: list[int]) -> int:
    left, right, best = 0, len(height) - 1, 0
    while left < right:
        best = max(best, (right - left) * min(height[left], height[right]))
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return best

function threeSum(nums: number[]): number[][] {
    const res: number[][] = [];
    // 先排序，为去重和双指针创造条件
    nums.sort((a, b) => a - b);

    for (let i = 0; i < nums.length - 2; i++) {
        // 跳过重复的第一个数
        if (i > 0 && nums[i] === nums[i - 1]) continue;

        let left = i + 1;
        let right = nums.length - 1;
        const target = -nums[i];

        while (left < right) {
            const sum = nums[left] + nums[right];

            if (sum === target) {
                res.push([nums[i], nums[left], nums[right]]);
                // 跳过重复的第二个数和第三个数
                while (left < right && nums[left] === nums[left + 1]) left++;
                while (left < right && nums[right] === nums[right - 1]) right--;
                left++;
                right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }
    }

    return res;
}

from typing import List

def threeSum(nums: List[int]) -> List[List[int]]:
    res: List[List[int]] = []
    nums.sort()  # 为双指针和去重做准备

    for i in range(len(nums) - 2):
        # 跳过重复的第一个数
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1
        target = -nums[i]

        while left < right:
            total = nums[left] + nums[right]

            if total == target:
                res.append([nums[i], nums[left], nums[right]])
                # 跳过重复的左右指针值
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < target:
                left += 1
            else:
                right -= 1

    return res

function trap(height: number[]): number {
  let l = 0, r = height.length - 1, lm = 0, rm = 0, water = 0;
  while (l <= r) {
    // 较低一侧的蓄水上界已经确定
    if (lm <= rm) {
      lm = Math.max(lm, height[l]);
      water += lm - height[l++];
    } else {
      rm = Math.max(rm, height[r]);
      water += rm - height[r--];
    }
  }
  return water;
}

def trap(height: list[int]) -> int:
    l, r, lm, rm, water = 0, len(height) - 1, 0, 0, 0
    while l <= r:
        if lm <= rm:
            lm = max(lm, height[l])
            water += lm - height[l]
            l += 1
        else:
            rm = max(rm, height[r])
            water += rm - height[r]
            r -= 1
    return water

function lengthOfLongestSubstring(s: string): number {
  const last = new Map<string, number>();
  let left = 0, best = 0;
  for (let right = 0; right < s.length; right++) {
    // 左边界只能向右移动
    left = Math.max(left, (last.get(s[right]) ?? -1) + 1);
    last.set(s[right], right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

def lengthOfLongestSubstring(s: str) -> int:
    last = {}
    left = best = 0
    for right, ch in enumerate(s):
        left = max(left, last.get(ch, -1) + 1)
        last[ch] = right
        best = max(best, right - left + 1)
    return best

function findAnagrams(s: string, p: string): number[] {
  const need = Array(26).fill(0), window = Array(26).fill(0), result: number[] = [];
  for (const ch of p) need[ch.charCodeAt(0) - 97]++;
  for (let i = 0; i < s.length; i++) {
    window[s.charCodeAt(i) - 97]++;
    if (i >= p.length) window[s.charCodeAt(i - p.length) - 97]--;
    // 固定长度窗口比较 26 个计数
    if (i >= p.length - 1 && window.every((v, j) => v === need[j])) result.push(i - p.length + 1);
  }
  return result;
}

def findAnagrams(s: str, p: str) -> list[int]:
    need, window, result = [0] * 26, [0] * 26, []
    for ch in p:
        need[ord(ch) - 97] += 1
    for i, ch in enumerate(s):
        window[ord(ch) - 97] += 1
        if i >= len(p):
            window[ord(s[i - len(p)]) - 97] -= 1
        if i >= len(p) - 1 and window == need:
            result.append(i - len(p) + 1)
    return result

function subarraySum(nums: number[], k: number): number {
  const counts = new Map<number, number>([[0, 1]]);
  let prefix = 0, result = 0;
  for (const x of nums) {
    prefix += x;
    // 两个前缀和的差就是中间子数组的和
    result += counts.get(prefix - k) ?? 0;
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
  }
  return result;
}

def subarraySum(nums: list[int], k: int) -> int:
    counts = {0: 1}
    prefix = result = 0
    for x in nums:
        prefix += x
        result += counts.get(prefix - k, 0)
        counts[prefix] = counts.get(prefix, 0) + 1
    return result

function maxSlidingWindow(nums: number[], k: number): number[] {
  const deque: number[] = [], result: number[] = [];
  let head = 0;
  for (let i = 0; i < nums.length; i++) {
    if (head < deque.length && deque[head] <= i - k) head++;
    // 队列按值递减，队首始终是当前最大值
    while (deque.length > head && nums[deque[deque.length - 1]] <= nums[i]) deque.pop();
    deque.push(i);
    if (i >= k - 1) result.push(nums[deque[head]]);
  }
  return result;
}

from collections import deque

def maxSlidingWindow(nums: list[int], k: int) -> list[int]:
    q, result = deque(), []
    for i, x in enumerate(nums):
        if q and q[0] <= i - k:
            q.popleft()
        while q and nums[q[-1]] <= x:
            q.pop()
        q.append(i)
        if i >= k - 1:
            result.append(nums[q[0]])
    return result

function minWindow(s: string, t: string): string {
  if (!t) return "";
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  let missing = t.length, left = 0, start = 0, length = Infinity;
  for (let right = 0; right < s.length; right++) {
    const c = s[right];
    if ((need.get(c) ?? 0) > 0) missing--;
    need.set(c, (need.get(c) ?? 0) - 1);
    // 满足覆盖后尽量缩小左边界
    while (missing === 0) {
      if (right - left + 1 < length) { start = left; length = right - left + 1; }
      const out = s[left++];
      need.set(out, (need.get(out) ?? 0) + 1);
      if (need.get(out)! > 0) missing++;
    }
  }
  return length === Infinity ? "" : s.slice(start, start + length);
}

from collections import Counter

def minWindow(s: str, t: str) -> str:
    if not t:
        return ""
    need = Counter(t)
    missing, left, start, length = len(t), 0, 0, float("inf")
    for right, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        while missing == 0:
            if right - left + 1 < length:
                start, length = left, right - left + 1
            out = s[left]
            left += 1
            need[out] += 1
            if need[out] > 0:
                missing += 1
    return "" if length == float("inf") else s[start:start + length]

function maxSubArray(nums: number[]): number {
  let ending = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    // 要么接在上一段后面，要么从当前数重新开始
    ending = Math.max(nums[i], ending + nums[i]);
    best = Math.max(best, ending);
  }
  return best;
}

def maxSubArray(nums: list[int]) -> int:
    ending = best = nums[0]
    for x in nums[1:]:
        ending = max(x, ending + x)
        best = max(best, ending)
    return best

function merge(intervals: number[][]): number[][] {
  intervals.sort((a, b) => a[0] - b[0]);
  const result: number[][] = [];
  for (const [start, end] of intervals) {
    const last = result[result.length - 1];
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else result.push([start, end]);
  }
  return result;
}

def merge(intervals: list[list[int]]) -> list[list[int]]:
    result = []
    for start, end in sorted(intervals):
        if result and start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)
        else:
            result.append([start, end])
    return result

function rotate(nums: number[], k: number): void {
  if (!nums.length) return;
  k %= nums.length;
  const reverse = (l: number, r: number) => {
    while (l < r) { [nums[l], nums[r]] = [nums[r], nums[l]]; l++; r--; }
  };
  // 整体翻转后分别翻转两段，恢复各段内顺序
  reverse(0, nums.length - 1);
  reverse(0, k - 1);
  reverse(k, nums.length - 1);
}

def rotate(nums: list[int], k: int) -> None:
    if not nums:
        return
    k %= len(nums)
    def reverse(l: int, r: int) -> None:
        while l < r:
            nums[l], nums[r] = nums[r], nums[l]
            l, r = l + 1, r - 1
    reverse(0, len(nums) - 1)
    reverse(0, k - 1)
    reverse(k, len(nums) - 1)

function productExceptSelf(nums: number[]): number[] {
  const result = Array(nums.length).fill(1);
  let prefix = 1, suffix = 1;
  for (let i = 0; i < nums.length; i++) {
    result[i] = prefix;
    prefix *= nums[i];
  }
  // 第二次扫描将右侧乘积乘进去
  for (let i = nums.length - 1; i >= 0; i--) {
    result[i] *= suffix;
    suffix *= nums[i];
  }
  return result;
}

def productExceptSelf(nums: list[int]) -> list[int]:
    result = [1] * len(nums)
    prefix = suffix = 1
    for i, x in enumerate(nums):
        result[i] = prefix
        prefix *= x
    for i in range(len(nums) - 1, -1, -1):
        result[i] *= suffix
        suffix *= nums[i]
    return result

function firstMissingPositive(nums: number[]): number {
  const n = nums.length;
  for (let i = 0; i < n; i++) {
    // 数字 x 应当放在下标 x-1，遇到重复值就停
    while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {
      const j = nums[i] - 1;
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  for (let i = 0; i < n; i++) if (nums[i] !== i + 1) return i + 1;
  return n + 1;
}

def firstMissingPositive(nums: list[int]) -> int:
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i, x in enumerate(nums):
        if x != i + 1:
            return i + 1
    return n + 1

function setZeroes(matrix: number[][]): void {
  const m = matrix.length, n = matrix[0].length;
  const rowZero = matrix[0].some(x => x === 0), colZero = matrix.some(row => row[0] === 0);
  // 第一行和第一列充当标记区
  for (let i = 1; i < m; i++) for (let j = 1; j < n; j++) {
    if (matrix[i][j] === 0) matrix[i][0] = matrix[0][j] = 0;
  }
  for (let i = 1; i < m; i++) for (let j = 1; j < n; j++) {
    if (matrix[i][0] === 0 || matrix[0][j] === 0) matrix[i][j] = 0;
  }
  if (rowZero) matrix[0].fill(0);
  if (colZero) for (const row of matrix) row[0] = 0;
}

def setZeroes(matrix: list[list[int]]) -> None:
    m, n = len(matrix), len(matrix[0])
    row_zero = 0 in matrix[0]
    col_zero = any(row[0] == 0 for row in matrix)
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    if row_zero:
        matrix[0][:] = [0] * n
    if col_zero:
        for row in matrix:
            row[0] = 0

function spiralOrder(matrix: number[][]): number[] {
  if (!matrix.length) return [];
  const result: number[] = [];
  let top = 0, bottom = matrix.length - 1, left = 0, right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let j = left; j <= right; j++) result.push(matrix[top][j]);
    top++;
    for (let i = top; i <= bottom; i++) result.push(matrix[i][right]);
    right--;
    if (top <= bottom) { for (let j = right; j >= left; j--) result.push(matrix[bottom][j]); bottom--; }
    if (left <= right) { for (let i = bottom; i >= top; i--) result.push(matrix[i][left]); left++; }
  }
  return result;
}

function rotate(matrix: number[][]): void {
  const n = matrix.length;
  // 转置再逐行翻转等价于顺时针旋转
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
  }
  for (const row of matrix) row.reverse();
}

def rotate(matrix: list[list[int]]) -> None:
    n = len(matrix)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    for row in matrix:
        row.reverse()

function searchMatrix(matrix: number[][], target: number): boolean {
  if (!matrix.length) return false;
  let row = 0, col = matrix[0].length - 1;
  while (row < matrix.length && col >= 0) {
    const x = matrix[row][col];
    if (x === target) return true;
    // 右上角可以一次排除一行或一列
    if (x > target) col--;
    else row++;
  }
  return false;
}

def searchMatrix(matrix: list[list[int]], target: int) -> bool:
    if not matrix:
        return False
    row, col = 0, len(matrix[0]) - 1
    while row < len(matrix) and col >= 0:
        x = matrix[row][col]
        if x == target:
            return True
        if x > target:
            col -= 1
        else:
            row += 1
    return False

function getIntersectionNode(headA: ListNode | null, headB: ListNode | null): ListNode | null {
  let a = headA, b = headB;
  // 各走完 A+B，总路程相等，抵消前缀长度差
  while (a !== b) {
    a = a ? a.next : headB;
    b = b ? b.next : headA;
  }
  return a;
}

def getIntersectionNode(headA: "ListNode | None", headB: "ListNode | None") -> "ListNode | None":
    a, b = headA, headB
    while a is not b:
        a = a.next if a else headB
        b = b.next if b else headA
    return a

function reverseList(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  while (head) {
    const next: ListNode | null = head.next;
    head.next = prev;
    prev = head;
    head = next;
  }
  return prev;
}

function isPalindrome(head: ListNode | null): boolean {
  if (!head) return true;
  const reverse = (node: ListNode | null): ListNode | null => {
    let prev: ListNode | null = null;
    while (node) { const next: ListNode | null = node.next; node.next = prev; prev = node; node = next; }
    return prev;
  };
  let slow = head, fast = head;
  while (fast.next && fast.next.next) { slow = slow.next!; fast = fast.next.next; }
  const second = reverse(slow.next);
  let a: ListNode | null = head, b = second, ok = true;
  while (b) { if (a!.val !== b.val) ok = false; a = a!.next; b = b.next; }
  slow.next = reverse(second);
  return ok;
}

def isPalindrome(head: "ListNode | None") -> bool:
    if not head:
        return True
    def reverse(node):
        prev = None
        while node:
            nxt = node.next
            node.next = prev
            prev, node = node, nxt
        return prev
    slow = fast = head
    while fast.next and fast.next.next:
        slow, fast = slow.next, fast.next.next
    second = reverse(slow.next)
    a, b, ok = head, second, True
    while b:
        if a.val != b.val:
            ok = False
        a, b = a.next, b.next
    slow.next = reverse(second)
    return ok

function hasCycle(head: ListNode | null): boolean {
  let slow = head, fast = head;
  while (fast?.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

def hasCycle(head: "ListNode | None") -> bool:
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

function detectCycle(head: ListNode | null): ListNode | null {
  let slow = head, fast = head;
  while (fast?.next) {
    slow = slow!.next;
    fast = fast.next.next;
    if (slow === fast) {
      let entry = head;
      // 相遇后从头和相遇点同步走，交点就是环入口
      while (entry !== slow) { entry = entry!.next; slow = slow!.next; }
      return entry;
    }
  }
  return null;
}

def detectCycle(head: "ListNode | None") -> "ListNode | None":
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            entry = head
            while entry is not slow:
                entry, slow = entry.next, slow.next
            return entry
    return None

function mergeTwoLists(a: ListNode | null, b: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  let tail = dummy;
  while (a && b) {
    if (a.val <= b.val) { tail.next = a; a = a.next; }
    else { tail.next = b; b = b.next; }
    tail = tail.next;
  }
  tail.next = a ?? b;
  return dummy.next;
}

def mergeTwoLists(a: "ListNode | None", b: "ListNode | None") -> "ListNode | None":
    dummy = ListNode(0)
    tail = dummy
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next

function addTwoNumbers(a: ListNode | null, b: ListNode | null): ListNode | null {
  const dummy = new ListNode(0);
  let tail = dummy, carry = 0;
  while (a || b || carry) {
    const sum = (a?.val ?? 0) + (b?.val ?? 0) + carry;
    tail.next = new ListNode(sum % 10);
    tail = tail.next;
    carry = Math.floor(sum / 10);
    a = a?.next ?? null;
    b = b?.next ?? null;
  }
  return dummy.next;
}

function removeNthFromEnd(head: ListNode | null, n: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let fast = dummy, slow = dummy;
  for (let i = 0; i < n; i++) fast = fast.next!;
  // 两指针间隔 n，慢指针停在待删节点之前
  while (fast.next) { fast = fast.next; slow = slow.next!; }
  slow.next = slow.next!.next;
  return dummy.next;
}

def removeNthFromEnd(head: "ListNode | None", n: int) -> "ListNode | None":
    dummy = ListNode(0, head)
    fast = slow = dummy
    for _ in range(n):
        fast = fast.next
    while fast.next:
        fast, slow = fast.next, slow.next
    slow.next = slow.next.next
    return dummy.next

function swapPairs(head: ListNode | null): ListNode | null {
  const dummy = new ListNode(0, head);
  let prev = dummy;
  while (prev.next?.next) {
    const a = prev.next, b = a.next!;
    a.next = b.next;
    b.next = a;
    prev.next = b;
    prev = a;
  }
  return dummy.next;
}

function reverseKGroup(head: ListNode | null, k: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let before = dummy;
  while (true) {
    let end: ListNode | null = before;
    for (let i = 0; i < k && end; i++) end = end.next;
    if (!end) break;
    const after = end.next, first = before.next!;
    let prev = after, cur: ListNode | null = first;
    // 只反转已经确认长度足够的一组
    while (cur !== after) {
      const next: ListNode | null = cur!.next;
      cur!.next = prev; prev = cur; cur = next;
    }
    before.next = end;
    before = first;
  }
  return dummy.next;
}

function copyRandomList(head: Node | null): Node | null {
  const copies = new Map<Node, Node>();
  for (let cur = head; cur; cur = cur.next) copies.set(cur, new Node(cur.val));
  // 先建节点，再连接，避免随机指针指向尚未创建的副本
  for (let cur = head; cur; cur = cur.next) {
    const copy = copies.get(cur)!;
    copy.next = cur.next ? copies.get(cur.next)! : null;
    copy.random = cur.random ? copies.get(cur.random)! : null;
  }
  return head ? copies.get(head)! : null;
}

def copyRandomList(head: "Node | None") -> "Node | None":
    copies = {}
    cur = head
    while cur:
        copies[cur] = Node(cur.val)
        cur = cur.next
    cur = head
    while cur:
        copies[cur].next = copies.get(cur.next)
        copies[cur].random = copies.get(cur.random)
        cur = cur.next
    return copies.get(head)

function sortList(head: ListNode | null): ListNode | null {
  let n = 0;
  for (let p = head; p; p = p.next) n++;
  const dummy = new ListNode(0, head);
  const split = (p: ListNode | null, size: number): ListNode | null => {
    for (let i = 1; p && i < size; i++) p = p.next;
    if (!p) return null;
    const rest = p.next; p.next = null; return rest;
  };
  for (let size = 1; size < n; size *= 2) {
    let cur = dummy.next, tail = dummy;
    while (cur) {
      let a: ListNode | null = cur, b = split(a, size);
      cur = split(b, size);
      while (a && b) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else { tail.next = b; b = b.next; }
        tail = tail.next;
      }
      tail.next = a ?? b;
      while (tail.next) tail = tail.next;
    }
  }
  return dummy.next;
}

def sortList(head: "ListNode | None") -> "ListNode | None":
    n, p = 0, head
    while p:
        n, p = n + 1, p.next
    dummy = ListNode(0, head)
    def split(p, size):
        for _ in range(size - 1):
            if p:
                p = p.next
        if not p:
            return None
        rest, p.next = p.next, None
        return rest
    size = 1
    while size < n:
        cur, tail = dummy.next, dummy
        while cur:
            a = cur
            b = split(a, size)
            cur = split(b, size)
            while a and b:
                if a.val <= b.val:
                    tail.next, a = a, a.next
                else:
                    tail.next, b = b, b.next
                tail = tail.next
            tail.next = a or b
            while tail.next:
                tail = tail.next
        size *= 2
    return dummy.next

function mergeKLists(lists: (ListNode | null)[]): ListNode | null {
  const merge = (a: ListNode | null, b: ListNode | null): ListNode | null => {
    const dummy = new ListNode(0); let tail = dummy;
    while (a && b) {
      if (a.val <= b.val) { tail.next = a; a = a.next; }
      else { tail.next = b; b = b.next; }
      tail = tail.next;
    }
    tail.next = a ?? b; return dummy.next;
  };
  // 每轮两两合并，轮数为 log k
  for (let size = 1; size < lists.length; size *= 2) {
    for (let i = 0; i + size < lists.length; i += size * 2) lists[i] = merge(lists[i], lists[i + size]);
  }
  return lists[0] ?? null;
}

def mergeKLists(lists: list) -> "ListNode | None":
    def merge(a, b):
        dummy = ListNode(0)
        tail = dummy
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next
    size = 1
    while size < len(lists):
        for i in range(0, len(lists) - size, size * 2):
            lists[i] = merge(lists[i], lists[i + size])
        size *= 2
    return lists[0] if lists else None

class LRUCache {
  private entries = new Map<number, number>();
  constructor(private capacity: number) {}
  get(key: number): number {
    if (!this.entries.has(key)) return -1;
    const value = this.entries.get(key)!;
    // Map 保持插入顺序，重新插入代表最近使用
    this.entries.delete(key);
    this.entries.set(key, value);
    return value;
  }
  put(key: number, value: number): void {
    this.entries.delete(key);
    this.entries.set(key, value);
    if (this.entries.size > this.capacity) this.entries.delete(this.entries.keys().next().value!);
  }
}

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.entries = OrderedDict()
    def get(self, key: int) -> int:
        if key not in self.entries:
            return -1
        self.entries.move_to_end(key)
        return self.entries[key]
    def put(self, key: int, value: int) -> None:
        self.entries[key] = value
        self.entries.move_to_end(key)
        if len(self.entries) > self.capacity:
            self.entries.popitem(last=False)

function inorderTraversal(root: TreeNode | null): number[] {
  const stack: TreeNode[] = [], result: number[] = [];
  let cur = root;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    cur = stack.pop()!;
    result.push(cur.val);
    cur = cur.right;
  }
  return result;
}

def inorderTraversal(root: "TreeNode | None") -> list[int]:
    stack, result, cur = [], [], root
    while cur or stack:
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        result.append(cur.val)
        cur = cur.right
    return result

function maxDepth(root: TreeNode | null): number {
  if (!root) return 0;
  // 当前高度等于较高子树的高度加一
  return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

def maxDepth(root: "TreeNode | None") -> int:
    if not root:
        return 0
    stack, best = [(root, 1)], 0
    while stack:
        node, depth = stack.pop()
        best = max(best, depth)
        if node.left:
            stack.append((node.left, depth + 1))
        if node.right:
            stack.append((node.right, depth + 1))
    return best

function invertTree(root: TreeNode | null): TreeNode | null {
  if (!root) return null;
  const left = invertTree(root.left);
  root.left = invertTree(root.right);
  root.right = left;
  return root;
}

def invertTree(root: "TreeNode | None") -> "TreeNode | None":
    stack = [root] if root else []
    while stack:
        node = stack.pop()
        node.left, node.right = node.right, node.left
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return root

function isSymmetric(root: TreeNode | null): boolean {
  const mirror = (a: TreeNode | null, b: TreeNode | null): boolean => {
    if (!a || !b) return a === b;
    return a.val === b.val && mirror(a.left, b.right) && mirror(a.right, b.left);
  };
  return !root || mirror(root.left, root.right);
}

def isSymmetric(root: "TreeNode | None") -> bool:
    if not root:
        return True
    stack = [(root.left, root.right)]
    while stack:
        a, b = stack.pop()
        if not a or not b:
            if a is not b:
                return False
            continue
        if a.val != b.val:
            return False
        stack.append((a.left, b.right))
        stack.append((a.right, b.left))
    return True

function diameterOfBinaryTree(root: TreeNode | null): number {
  let best = 0;
  const height = (node: TreeNode | null): number => {
    if (!node) return 0;
    const left = height(node.left), right = height(node.right);
    best = Math.max(best, left + right);
    return 1 + Math.max(left, right);
  };
  height(root);
  return best;
}

def diameterOfBinaryTree(root: "TreeNode | None") -> int:
    stack, heights, best = [(root, False)] if root else [], {}, 0
    while stack:
        node, visited = stack.pop()
        if not visited:
            # 出栈事件模拟递归返回，孩子先计算高度
            stack.append((node, True))
            if node.right:
                stack.append((node.right, False))
            if node.left:
                stack.append((node.left, False))
        else:
            left, right = heights.get(node.left, 0), heights.get(node.right, 0)
            best = max(best, left + right)
            heights[node] = 1 + max(left, right)
    return best

function levelOrder(root: TreeNode | null): number[][] {
  if (!root) return [];
  const queue: TreeNode[] = [root], result: number[][] = [];
  let head = 0;
  while (head < queue.length) {
    const end = queue.length, level: number[] = [];
    // 本层边界固定，新入队的孩子属于下一层
    while (head < end) {
      const node = queue[head++]; level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}

def levelOrder(root: "TreeNode | None") -> list[list[int]]:
    result, stack = [], [(root, 0)] if root else []
    while stack:
        node, depth = stack.pop()
        if depth == len(result):
            result.append([])
        result[depth].append(node.val)
        # 右侧先入栈，左侧先访问，保留每层从左到右顺序
        if node.right:
            stack.append((node.right, depth + 1))
        if node.left:
            stack.append((node.left, depth + 1))
    return result

function sortedArrayToBST(nums: number[]): TreeNode | null {
  const build = (left: number, right: number): TreeNode | null => {
    if (left > right) return null;
    const mid = Math.floor((left + right) / 2);
    // 中点作根，两侧分别构建，保证高度平衡
    return new TreeNode(nums[mid], build(left, mid - 1), build(mid + 1, right));
  };
  return build(0, nums.length - 1);
}

function isValidBST(root: TreeNode | null): boolean {
  const check = (node: TreeNode | null, low: number, high: number): boolean => {
    if (!node) return true;
    if (node.val <= low || node.val >= high) return false;
    return check(node.left, low, node.val) && check(node.right, node.val, high);
  };
  return check(root, -Infinity, Infinity);
}

def isValidBST(root: "TreeNode | None") -> bool:
    stack = [(root, float("-inf"), float("inf"))] if root else []
    while stack:
        node, low, high = stack.pop()
        if not low < node.val < high:
            return False
        if node.right:
            stack.append((node.right, node.val, high))
        if node.left:
            stack.append((node.left, low, node.val))
    return True

function kthSmallest(root: TreeNode | null, k: number): number {
  const stack: TreeNode[] = [];
  let cur = root;
  while (cur || stack.length) {
    while (cur) { stack.push(cur); cur = cur.left; }
    cur = stack.pop()!;
    // 搜索树中序遍历就是递增顺序
    if (--k === 0) return cur.val;
    cur = cur.right;
  }
  throw new Error("k 超出节点数");
}

def kthSmallest(root: "TreeNode | None", k: int) -> int:
    stack, cur = [], root
    while cur or stack:
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        k -= 1
        if k == 0:
            return cur.val
        cur = cur.right
    raise ValueError("k 超出节点数")

function rightSideView(root: TreeNode | null): number[] {
  const result: number[] = [];
  const visit = (node: TreeNode | null, depth: number): void => {
    if (!node) return;
    // 先走右侧，每层首次遇到的就是最右节点
    if (depth === result.length) result.push(node.val);
    visit(node.right, depth + 1);
    visit(node.left, depth + 1);
  };
  visit(root, 0);
  return result;
}

def rightSideView(root: "TreeNode | None") -> list[int]:
    result, stack = [], [(root, 0)] if root else []
    while stack:
        node, depth = stack.pop()
        if depth == len(result):
            result.append(node.val)
        # 右侧先访问，每层首次出现的就是可见节点
        if node.left:
            stack.append((node.left, depth + 1))
        if node.right:
            stack.append((node.right, depth + 1))
    return result

function flatten(root: TreeNode | null): void {
  let cur = root;
  while (cur) {
    if (cur.left) {
      let tail = cur.left;
      while (tail.right) tail = tail.right;
      // 左子树插到当前节点与原右子树之间
      tail.right = cur.right;
      cur.right = cur.left;
      cur.left = null;
    }
    cur = cur.right;
  }
}

def flatten(root: "TreeNode | None") -> None:
    cur = root
    while cur:
        if cur.left:
            tail = cur.left
            while tail.right:
                tail = tail.right
            tail.right = cur.right
            cur.right = cur.left
            cur.left = None
        cur = cur.right

function buildTree(preorder: number[], inorder: number[]): TreeNode | null {
  const index = new Map(inorder.map((value, i) => [value, i]));
  let pos = 0;
  const build = (left: number, right: number): TreeNode | null => {
    if (left > right) return null;
    const value = preorder[pos++], mid = index.get(value)!;
    const node = new TreeNode(value);
    node.left = build(left, mid - 1);
    node.right = build(mid + 1, right);
    return node;
  };
  return build(0, inorder.length - 1);
}

def buildTree(preorder: list[int], inorder: list[int]) -> "TreeNode | None":
    if not preorder:
        return None
    root = TreeNode(preorder[0])
    stack, pos = [root], 0
    for value in preorder[1:]:
        node = TreeNode(value)
        if stack[-1].val != inorder[pos]:
            stack[-1].left = node
        else:
            # 中序已经经过的节点出栈，新节点接到最后一个的右侧
            parent = None
            while stack and stack[-1].val == inorder[pos]:
                parent = stack.pop()
                pos += 1
            parent.right = node
        stack.append(node)
    return root

function pathSum(root: TreeNode | null, targetSum: number): number {
  const counts = new Map<number, number>([[0, 1]]);
  const visit = (node: TreeNode | null, prefix: number): number => {
    if (!node) return 0;
    prefix += node.val;
    let result = counts.get(prefix - targetSum) ?? 0;
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
    result += visit(node.left, prefix) + visit(node.right, prefix);
    // 回溯时移除当前前缀，兄弟分支不能相互拼接
    counts.set(prefix, counts.get(prefix)! - 1);
    return result;
  };
  return visit(root, 0);
}

function lowestCommonAncestor(root: TreeNode | null, p: TreeNode, q: TreeNode): TreeNode | null {
  if (!root || root === p || root === q) return root;
  const left = lowestCommonAncestor(root.left, p, q);
  const right = lowestCommonAncestor(root.right, p, q);
  // 两侧都找到目标，当前根就是最近公共祖先
  if (left && right) return root;
  return left ?? right;
}

def lowestCommonAncestor(root: "TreeNode | None", p: "TreeNode", q: "TreeNode") -> "TreeNode | None":
    if not root:
        return None
    parents, stack = {root: None}, [root]
    while stack and (p not in parents or q not in parents):
        node = stack.pop()
        for child in (node.left, node.right):
            if child:
                parents[child] = node
                stack.append(child)
    ancestors = set()
    while p:
        ancestors.add(p)
        p = parents[p]
    while q not in ancestors:
        q = parents[q]
    return q

function maxPathSum(root: TreeNode | null): number {
  let best = -Infinity;
  const gain = (node: TreeNode | null): number => {
    if (!node) return 0;
    const left = Math.max(0, gain(node.left)), right = Math.max(0, gain(node.right));
    best = Math.max(best, node.val + left + right);
    // 向父节点延伸时只能选择一侧，不能产生分叉
    return node.val + Math.max(left, right);
  };
  gain(root);
  return best;
}

def maxPathSum(root: "TreeNode | None") -> int:
    stack, gains, best = [(root, False)], {}, float("-inf")
    while stack:
        node, visited = stack.pop()
        if not visited:
            stack.append((node, True))
            if node.right:
                stack.append((node.right, False))
            if node.left:
                stack.append((node.left, False))
        else:
            left, right = max(0, gains.get(node.left, 0)), max(0, gains.get(node.right, 0))
            best = max(best, node.val + left + right)
            gains[node] = node.val + max(left, right)
    return best

function numIslands(grid: string[][]): number {
  if (!grid.length) return 0;
  const m = grid.length, n = grid[0].length;
  let count = 0;
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) {
    if (grid[r][c] !== "1") continue;
    count++;
    const stack: number[][] = [[r, c]]; grid[r][c] = "0";
    while (stack.length) {
      const [x, y] = stack.pop()!;
      for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
        const a = x + dx, b = y + dy;
        if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] === "1") {
          grid[a][b] = "0"; stack.push([a, b]);
        }
      }
    }
  }
  return count;
}

def numIslands(grid: list[list[str]]) -> int:
    if not grid:
        return 0
    m, n, count = len(grid), len(grid[0]), 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] != "1":
                continue
            count += 1
            stack = [(r, c)]
            grid[r][c] = "0"
            while stack:
                x, y = stack.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < m and 0 <= b < n and grid[a][b] == "1":
                        grid[a][b] = "0"
                        stack.append((a, b))
    return count

function orangesRotting(grid: number[][]): number {
  const m = grid.length, n = grid[0].length, queue: number[][] = [];
  let fresh = 0, head = 0, minutes = 0;
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
    if (grid[i][j] === 2) queue.push([i, j]);
    if (grid[i][j] === 1) fresh++;
  }
  // 所有腐烂点同时出发，每一层代表一分钟
  while (fresh && head < queue.length) {
    const end = queue.length; minutes++;
    while (head < end) {
      const [x, y] = queue[head++];
      for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
        const a = x + dx, b = y + dy;
        if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] === 1) {
          grid[a][b] = 2; fresh--; queue.push([a, b]);
        }
      }
    }
  }
  return fresh ? -1 : minutes;
}

from collections import deque

def orangesRotting(grid: list[list[int]]) -> int:
    m, n, queue, fresh, minutes = len(grid), len(grid[0]), deque(), 0, 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                queue.append((i, j))
            elif grid[i][j] == 1:
                fresh += 1
    while fresh and queue:
        minutes += 1
        for _ in range(len(queue)):
            x, y = queue.popleft()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = x + dx, y + dy
                if 0 <= a < m and 0 <= b < n and grid[a][b] == 1:
                    grid[a][b] = 2
                    fresh -= 1
                    queue.append((a, b))
    return -1 if fresh else minutes

function canFinish(numCourses: number, prerequisites: number[][]): boolean {
  const graph: number[][] = Array.from({ length: numCourses }, () => []);
  const indegree = Array(numCourses).fill(0), queue: number[] = [];
  for (const [a, b] of prerequisites) { graph[b].push(a); indegree[a]++; }
  for (let i = 0; i < numCourses; i++) if (indegree[i] === 0) queue.push(i);
  // 拓扑排序能移除全部节点就没有环
  for (let head = 0; head < queue.length; head++) {
    for (const next of graph[queue[head]]) if (--indegree[next] === 0) queue.push(next);
  }
  return queue.length === numCourses;
}

from collections import deque

def canFinish(numCourses: int, prerequisites: list[list[int]]) -> bool:
    graph, indegree = [[] for _ in range(numCourses)], [0] * numCourses
    for a, b in prerequisites:
        graph[b].append(a)
        indegree[a] += 1
    queue = deque(i for i in range(numCourses) if indegree[i] == 0)
    completed = 0
    while queue:
        node = queue.popleft()
        completed += 1
        for nxt in graph[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                queue.append(nxt)
    return completed == numCourses

class TrieNode {
  children = new Map<string, TrieNode>();
  terminal = false;
}
class Trie {
  private root = new TrieNode();
  insert(word: string): void {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch)!;
    }
    node.terminal = true;
  }
  private find(word: string): TrieNode | undefined {
    let node: TrieNode | undefined = this.root;
    for (const ch of word) { node = node.children.get(ch); if (!node) return undefined; }
    return node;
  }
  search(word: string): boolean { return this.find(word)?.terminal ?? false; }
  startsWith(prefix: string): boolean { return this.find(prefix) !== undefined; }
}

class Trie:
    def __init__(self):
        self.root = {}
    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["#"] = True
    def _find(self, word: str):
        node = self.root
        for ch in word:
            if ch not in node:
                return None
            node = node[ch]
        return node
    def search(self, word: str) -> bool:
        node = self._find(word)
        return node is not None and "#" in node
    def startsWith(self, prefix: str) -> bool:
        return self._find(prefix) is not None

function permute(nums: number[]): number[][] {
  const result: number[][] = [], path: number[] = [], used = Array(nums.length).fill(false);
  const dfs = (): void => {
    if (path.length === nums.length) { result.push([...path]); return; }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true; path.push(nums[i]);
      dfs();
      path.pop(); used[i] = false;
    }
  };
  dfs(); return result;
}

def permute(nums: list[int]) -> list[list[int]]:
    result, path, used = [], [], [False] * len(nums)
    def dfs():
        if len(path) == len(nums):
            result.append(path[:])
            return
        for i, x in enumerate(nums):
            if used[i]:
                continue
            used[i] = True
            path.append(x)
            dfs()
            path.pop()
            used[i] = False
    dfs()
    return result

function subsets(nums: number[]): number[][] {
  const result: number[][] = [[]];
  for (const x of nums) {
    const size = result.length;
    // 给已有的每个子集追加当前元素，得到新的一半
    for (let i = 0; i < size; i++) result.push([...result[i], x]);
  }
  return result;
}

def subsets(nums: list[int]) -> list[list[int]]:
    result = [[]]
    for x in nums:
        result += [part + [x] for part in result]
    return result

function letterCombinations(digits: string): string[] {
  if (!digits) return [];
  const letters = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
  let result = [""];
  for (const digit of digits) {
    const next: string[] = [];
    for (const prefix of result) for (const ch of letters[Number(digit)]) next.push(prefix + ch);
    result = next;
  }
  return result;
}

def letterCombinations(digits: str) -> list[str]:
    if not digits:
        return []
    letters = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"]
    result = [""]
    for digit in digits:
        result = [prefix + ch for prefix in result for ch in letters[int(digit)]]
    return result

function combinationSum(candidates: number[], target: number): number[][] {
  candidates.sort((a, b) => a - b);
  const result: number[][] = [], path: number[] = [];
  const dfs = (start: number, remaining: number): void => {
    if (remaining === 0) { result.push([...path]); return; }
    for (let i = start; i < candidates.length && candidates[i] <= remaining; i++) {
      path.push(candidates[i]);
      dfs(i, remaining - candidates[i]);
      path.pop();
    }
  };
  dfs(0, target); return result;
}

def combinationSum(candidates: list[int], target: int) -> list[list[int]]:
    candidates.sort()
    result, path = [], []
    def dfs(start, remaining):
        if remaining == 0:
            result.append(path[:])
            return
        for i in range(start, len(candidates)):
            if candidates[i] > remaining:
                break
            path.append(candidates[i])
            dfs(i, remaining - candidates[i])
            path.pop()
    dfs(0, target)
    return result

function generateParenthesis(n: number): string[] {
  const result: string[] = [];
  const dfs = (text: string, left: number, right: number): void => {
    if (text.length === 2 * n) { result.push(text); return; }
    if (left < n) dfs(text + "(", left + 1, right);
    if (right < left) dfs(text + ")", left, right + 1);
  };
  dfs("", 0, 0);
  return result;
}

def generateParenthesis(n: int) -> list[str]:
    result = []
    def dfs(text, left, right):
        if len(text) == 2 * n:
            result.append(text)
            return
        if left < n:
            dfs(text + "(", left + 1, right)
        if right < left:
            dfs(text + ")", left, right + 1)
    dfs("", 0, 0)
    return result

function exist(board: string[][], word: string): boolean {
  const m = board.length, n = board[0].length;
  const dfs = (r: number, c: number, i: number): boolean => {
    if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] !== word[i]) return false;
    if (i === word.length - 1) return true;
    const ch = board[r][c]; board[r][c] = "#";
    const found = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
    board[r][c] = ch;
    return found;
  };
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) if (dfs(r, c, 0)) return true;
  return false;
}

def exist(board: list[list[str]], word: str) -> bool:
    m, n = len(board), len(board[0])
    def dfs(r, c, i):
        if not (0 <= r < m and 0 <= c < n) or board[r][c] != word[i]:
            return False
        if i == len(word) - 1:
            return True
        ch, board[r][c] = board[r][c], "#"
        found = any(dfs(r + dr, c + dc, i + 1) for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
        board[r][c] = ch
        return found
    return any(dfs(r, c, 0) for r in range(m) for c in range(n))

function partition(s: string): string[][] {
  const n = s.length, palindrome: boolean[][] = Array.from({ length: n }, () => Array(n).fill(false));
  for (let l = n - 1; l >= 0; l--) for (let r = l; r < n; r++) {
    palindrome[l][r] = s[l] === s[r] && (r - l < 2 || palindrome[l + 1][r - 1]);
  }
  const result: string[][] = [], path: string[] = [];
  const dfs = (start: number): void => {
    if (start === n) { result.push([...path]); return; }
    for (let end = start; end < n; end++) if (palindrome[start][end]) {
      path.push(s.slice(start, end + 1)); dfs(end + 1); path.pop();
    }
  };
  dfs(0); return result;
}

def partition(s: str) -> list[list[str]]:
    n = len(s)
    palindrome = [[False] * n for _ in range(n)]
    for l in range(n - 1, -1, -1):
        for r in range(l, n):
            palindrome[l][r] = s[l] == s[r] and (r - l < 2 or palindrome[l + 1][r - 1])
    result, path = [], []
    def dfs(start):
        if start == n:
            result.append(path[:])
            return
        for end in range(start, n):
            if palindrome[start][end]:
                path.append(s[start:end + 1])
                dfs(end + 1)
                path.pop()
    dfs(0)
    return result

function solveNQueens(n: number): string[][] {
  const result: string[][] = [], path: number[] = [], cols = new Set<number>(), down = new Set<number>(), up = new Set<number>();
  const dfs = (row: number): void => {
    if (row === n) { result.push(path.map(c => ".".repeat(c) + "Q" + ".".repeat(n - c - 1))); return; }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || down.has(row - c) || up.has(row + c)) continue;
      cols.add(c); down.add(row - c); up.add(row + c); path.push(c);
      dfs(row + 1);
      path.pop(); cols.delete(c); down.delete(row - c); up.delete(row + c);
    }
  };
  dfs(0); return result;
}

function searchInsert(nums: number[], target: number): number {
  let left = 0, right = nums.length;
  // 半开区间寻找第一个不小于 target 的位置
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (nums[mid] < target) left = mid + 1;
    else right = mid;
  }
  return left;
}

def searchInsert(nums: list[int], target: int) -> int:
    left, right = 0, len(nums)
    while left < right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

function searchMatrix(matrix: number[][], target: number): boolean {
  if (!matrix.length || !matrix[0].length) return false;
  const n = matrix[0].length;
  let left = 0, right = matrix.length * n - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2), value = matrix[Math.floor(mid / n)][mid % n];
    if (value === target) return true;
    if (value < target) left = mid + 1;
    else right = mid - 1;
  }
  return false;
}

def searchMatrix(matrix: list[list[int]], target: int) -> bool:
    if not matrix or not matrix[0]:
        return False
    n = len(matrix[0])
    left, right = 0, len(matrix) * n - 1
    while left <= right:
        mid = (left + right) // 2
        value = matrix[mid // n][mid % n]
        if value == target:
            return True
        if value < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

function searchRange(nums: number[], target: number): number[] {
  const bound = (strict: boolean): number => {
    let left = 0, right = nums.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (nums[mid] < target || (strict && nums[mid] === target)) left = mid + 1;
      else right = mid;
    }
    return left;
  };
  const first = bound(false);
  return nums[first] === target ? [first, bound(true) - 1] : [-1, -1];
}

def searchRange(nums: list[int], target: int) -> list[int]:
    def bound(strict):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target or (strict and nums[mid] == target):
                left = mid + 1
            else:
                right = mid
        return left
    first = bound(False)
    return [first, bound(True) - 1] if first < len(nums) and nums[first] == target else [-1, -1]

function search(nums: number[], target: number): number {
  let left = 0, right = nums.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (nums[mid] === target) return mid;
    // 至少有一半保持递增，可判断目标是否在其中
    if (nums[left] <= nums[mid]) {
      if (nums[left] <= target && target < nums[mid]) right = mid - 1;
      else left = mid + 1;
    } else {
      if (nums[mid] < target && target <= nums[right]) left = mid + 1;
      else right = mid - 1;
    }
  }
  return -1;
}

def search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

function findMin(nums: number[]): number {
