function findMedianSortedArrays(a: number[], b: number[]): number {
  if (a.length > b.length) return findMedianSortedArrays(b, a);
  const m = a.length, n = b.length, half = Math.floor((m + n + 1) / 2);
  let low = 0, high = m;
  while (low <= high) {
    const i = Math.floor((low + high) / 2), j = half - i;
    const al = i ? a[i - 1] : -Infinity, ar = i < m ? a[i] : Infinity;
    const bl = j ? b[j - 1] : -Infinity, br = j < n ? b[j] : Infinity;
    // 左半部的所有数都不能超过右半部
    if (al <= br && bl <= ar) {
      return (m + n) % 2 ? Math.max(al, bl) : (Math.max(al, bl) + Math.min(ar, br)) / 2;
    }
    if (al > br) high = i - 1;
    else low = i + 1;
  }
  throw new Error("输入必须有序");
}

def findMedianSortedArrays(a: list[int], b: list[int]) -> float:
    if len(a) > len(b):
        return findMedianSortedArrays(b, a)
    m, n = len(a), len(b)
    half, low, high = (m + n + 1) // 2, 0, m
    while low <= high:
        i = (low + high) // 2
        j = half - i
        al, ar = a[i - 1] if i else float("-inf"), a[i] if i < m else float("inf")
        bl, br = b[j - 1] if j else float("-inf"), b[j] if j < n else float("inf")
        if al <= br and bl <= ar:
            return max(al, bl) if (m + n) % 2 else (max(al, bl) + min(ar, br)) / 2
        if al > br:
            high = i - 1
        else:
            low = i + 1
    raise ValueError("输入必须有序")

function isValid(s: string): boolean {
  const stack: string[] = [], pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  for (const ch of s) {
    if (ch in pairs) { if (stack.pop() !== pairs[ch]) return false; }
    else stack.push(ch);
  }
  return stack.length === 0;
}

def isValid(s: str) -> bool:
    stack, pairs = [], {")": "(", "]": "[", "}": "{"}
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

class MinStack {
  private values: number[] = [];
  private minima: number[] = [];
  push(val: number): void {
    this.values.push(val);
    // 每一层记录截至该层的最小值，重复最小值也能正确弹出
    this.minima.push(Math.min(val, this.minima[this.minima.length - 1] ?? Infinity));
  }
  pop(): void { this.values.pop(); this.minima.pop(); }
  top(): number { return this.values[this.values.length - 1]; }
  getMin(): number { return this.minima[this.minima.length - 1]; }
}

class MinStack:
    def __init__(self):
        self.values, self.minima = [], []
    def push(self, val: int) -> None:
        self.values.append(val)
        self.minima.append(min(val, self.minima[-1] if self.minima else val))
    def pop(self) -> None:
        self.values.pop()
        self.minima.pop()
    def top(self) -> int:
        return self.values[-1]
    def getMin(self) -> int:
        return self.minima[-1]

function decodeString(s: string): string {
  const stack: [string, number][] = [];
  let text = "", count = 0;
  for (const ch of s) {
    if (ch >= "0" && ch <= "9") count = count * 10 + Number(ch);
    else if (ch === "[") { stack.push([text, count]); text = ""; count = 0; }
    else if (ch === "]") { const [prefix, times] = stack.pop()!; text = prefix + text.repeat(times); }
    else text += ch;
  }
  return text;
}

def decodeString(s: str) -> str:
    stack, text, count = [], "", 0
    for ch in s:
        if ch.isdigit():
            count = count * 10 + int(ch)
        elif ch == "[":
            stack.append((text, count))
            text, count = "", 0
        elif ch == "]":
            prefix, times = stack.pop()
            text = prefix + text * times
        else:
            text += ch
    return text

function dailyTemperatures(temperatures: number[]): number[] {
  const result = Array(temperatures.length).fill(0), stack: number[] = [];
  for (let i = 0; i < temperatures.length; i++) {
    // 当前温度为之前等待中的较低温度结算答案
    while (stack.length && temperatures[stack[stack.length - 1]] < temperatures[i]) {
      const prev = stack.pop()!; result[prev] = i - prev;
    }
    stack.push(i);
  }
  return result;
}

def dailyTemperatures(temperatures: list[int]) -> list[int]:
    result, stack = [0] * len(temperatures), []
    for i, value in enumerate(temperatures):
        while stack and temperatures[stack[-1]] < value:
            prev = stack.pop()
            result[prev] = i - prev
        stack.append(i)
    return result

function largestRectangleArea(heights: number[]): number {
  const stack: number[] = [-1];
  let best = 0;
  for (let i = 0; i <= heights.length; i++) {
    const current = i === heights.length ? 0 : heights[i];
    while (stack.length > 1 && heights[stack[stack.length - 1]] > current) {
      const height = heights[stack.pop()!];
      // 弹出时左右第一个更低柱子都已确定
      best = Math.max(best, height * (i - stack[stack.length - 1] - 1));
    }
    stack.push(i);
  }
  return best;
}

def largestRectangleArea(heights: list[int]) -> int:
    stack, best = [-1], 0
    for i in range(len(heights) + 1):
        current = heights[i] if i < len(heights) else 0
        while len(stack) > 1 and heights[stack[-1]] > current:
            height = heights[stack.pop()]
            best = max(best, height * (i - stack[-1] - 1))
        stack.append(i)
    return best

// 二叉堆：优先级由 less 决定，push/pop 都是 O(log n)
class NumberHeap {
  data: number[] = [];
  constructor(private less: (a: number, b: number) => boolean) {}
  push(value: number): void {
    const a = this.data; a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (!this.less(a[i], a[p])) break;
      [a[i], a[p]] = [a[p], a[i]]; i = p;
    }
  }
  pop(): number {
    const a = this.data, root = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      while (i * 2 + 1 < a.length) {
        let child = i * 2 + 1;
        if (child + 1 < a.length && this.less(a[child + 1], a[child])) child++;
        if (!this.less(a[child], a[i])) break;
        [a[i], a[child]] = [a[child], a[i]]; i = child;
      }
    }
    return root;
  }
}

function findKthLargest(nums: number[], k: number): number {
  const heap = new NumberHeap((a, b) => a < b);
  for (const x of nums) {
    heap.push(x);
    if (heap.data.length > k) heap.pop();
  }
  return heap.data[0];
}

