function topKFrequent(nums: number[], k: number): number[] {
  const counts = new Map<number, number>();
  for (const x of nums) counts.set(x, (counts.get(x) ?? 0) + 1);
  const buckets: number[][] = Array.from({ length: nums.length + 1 }, () => []);
  for (const [x, count] of counts) buckets[count].push(x);
  const result: number[] = [];
  for (let count = nums.length; count >= 1; count--) {
    for (const x of buckets[count]) { result.push(x); if (result.length === k) return result; }
  }
  return result;
}

from collections import Counter

def topKFrequent(nums: list[int], k: int) -> list[int]:
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, count in Counter(nums).items():
        buckets[count].append(x)
    result = []
    for count in range(len(nums), 0, -1):
        for x in buckets[count]:
            result.append(x)
            if len(result) == k:
                return result
    return result

