class MedianFinder {
  private lower = new NumberHeap((a, b) => a > b);
  private upper = new NumberHeap((a, b) => a < b);
  addNum(num: number): void {
    this.lower.push(num);
    this.upper.push(this.lower.pop());
    if (this.upper.data.length > this.lower.data.length) this.lower.push(this.upper.pop());
  }
  findMedian(): number {
    return this.lower.data.length > this.upper.data.length ? this.lower.data[0] : (this.lower.data[0] + this.upper.data[0]) / 2;
  }
}

import heapq

class MedianFinder:
    def __init__(self):
        self.lower, self.upper = [], []
    def addNum(self, num: int) -> None:
        heapq.heappush(self.lower, -num)
        heapq.heappush(self.upper, -heapq.heappop(self.lower))
        if len(self.upper) > len(self.lower):
            heapq.heappush(self.lower, -heapq.heappop(self.upper))
    def findMedian(self) -> float:
        if len(self.lower) > len(self.upper):
            return -self.lower[0]
        return (-self.lower[0] + self.upper[0]) / 2

function maxProfit(prices: number[]): number {
  let lowest = Infinity, best = 0;
  for (const price of prices) {
    lowest = Math.min(lowest, price);
    best = Math.max(best, price - lowest);
  }
  return best;
}

def maxProfit(prices: list[int]) -> int:
    lowest, best = float("inf"), 0
    for price in prices:
        lowest = min(lowest, price)
        best = max(best, price - lowest)
    return best

function canJump(nums: number[]): boolean {
  let reach = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > reach) return false;
    reach = Math.max(reach, i + nums[i]);
  }
  return true;
}

def canJump(nums: list[int]) -> bool:
    reach = 0
    for i, x in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + x)
    return True

function jump(nums: number[]): number {
  let end = 0, farthest = 0, steps = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    farthest = Math.max(farthest, i + nums[i]);
    // 到达本次跳跃的覆盖边界，才需要开启下一跳
    if (i === end) { steps++; end = farthest; }
  }
  return steps;
}

def jump(nums: list[int]) -> int:
    end = farthest = steps = 0
    for i in range(len(nums) - 1):
        farthest = max(farthest, i + nums[i])
        if i == end:
            steps += 1
            end = farthest
    return steps

function partitionLabels(s: string): number[] {
  const last = new Map<string, number>(), result: number[] = [];
  for (let i = 0; i < s.length; i++) last.set(s[i], i);
  let start = 0, end = 0;
  for (let i = 0; i < s.length; i++) {
    end = Math.max(end, last.get(s[i])!);
    // 所有已出现字符的最后位置都已覆盖，才能切段
    if (i === end) { result.push(end - start + 1); start = i + 1; }
  }
  return result;
}

def partitionLabels(s: str) -> list[int]:
    last = {ch: i for i, ch in enumerate(s)}
    start = end = 0
    result = []
    for i, ch in enumerate(s):
        end = max(end, last[ch])
        if i == end:
            result.append(end - start + 1)
            start = i + 1
    return result

function climbStairs(n: number): number {
  let prev = 1, curr = 1;
  // 到第 i 级的方法来自第 i-1 和第 i-2 级
  for (let i = 2; i <= n; i++) [prev, curr] = [curr, prev + curr];
  return curr;
}

def climbStairs(n: int) -> int:
    prev = curr = 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

function generate(numRows: number): number[][] {
  const result: number[][] = [];
  for (let row = 0; row < numRows; row++) {
    const values = Array(row + 1).fill(1);
    for (let j = 1; j < row; j++) values[j] = result[row - 1][j - 1] + result[row - 1][j];
    result.push(values);
  }
  return result;
}

def generate(numRows: int) -> list[list[int]]:
    result = []
    for row in range(numRows):
        values = [1] * (row + 1)
        for j in range(1, row):
            values[j] = result[row - 1][j - 1] + result[row - 1][j]
        result.append(values)
    return result

function rob(nums: number[]): number {
  let twoBack = 0, oneBack = 0;
  for (const money of nums) {
    // 当前房屋：选择则加上隔一间的最优解，否则沿用前一间
    [twoBack, oneBack] = [oneBack, Math.max(oneBack, twoBack + money)];
  }
  return oneBack;
}

def rob(nums: list[int]) -> int:
    two_back = one_back = 0
    for money in nums:
        two_back, one_back = one_back, max(one_back, two_back + money)
    return one_back

function numSquares(n: number): number {
  const dp = Array(n + 1).fill(Infinity); dp[0] = 0;
  for (let value = 1; value <= n; value++) {
    for (let root = 1; root * root <= value; root++) {
      dp[value] = Math.min(dp[value], dp[value - root * root] + 1);
    }
  }
  return dp[n];
}

def numSquares(n: int) -> int:
    dp = [0] + [n + 1] * n
    for value in range(1, n + 1):
        root = 1
        while root * root <= value:
            dp[value] = min(dp[value], dp[value - root * root] + 1)
            root += 1
    return dp[n]

function coinChange(coins: number[], amount: number): number {
  const dp = Array(amount + 1).fill(amount + 1); dp[0] = 0;
  for (let value = 1; value <= amount; value++) {
    for (const coin of coins) if (coin <= value) dp[value] = Math.min(dp[value], dp[value - coin] + 1);
  }
  return dp[amount] > amount ? -1 : dp[amount];
}

def coinChange(coins: list[int], amount: int) -> int:
    dp = [0] + [amount + 1] * amount
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value:
                dp[value] = min(dp[value], dp[value - coin] + 1)
    return -1 if dp[amount] > amount else dp[amount]

function wordBreak(s: string, wordDict: string[]): boolean {
  const words = new Set(wordDict), dp = Array(s.length + 1).fill(false);
  const maxLength = Math.max(0, ...wordDict.map(w => w.length));
  dp[0] = true;
  for (let end = 1; end <= s.length; end++) {
    for (let start = end - 1; start >= Math.max(0, end - maxLength); start--) {
      if (dp[start] && words.has(s.slice(start, end))) { dp[end] = true; break; }
    }
  }
  return dp[s.length];
}

def wordBreak(s: str, wordDict: list[str]) -> bool:
    words = set(wordDict)
    max_length = max(map(len, wordDict), default=0)
    dp = [True] + [False] * len(s)
    for end in range(1, len(s) + 1):
        for start in range(end - 1, max(-1, end - max_length - 1), -1):
            if dp[start] and s[start:end] in words:
                dp[end] = True
                break
    return dp[-1]

function lengthOfLIS(nums: number[]): number {
  const tails: number[] = [];
  for (const x of nums) {
    let left = 0, right = tails.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (tails[mid] < x) left = mid + 1;
      else right = mid;
    }
    // tails[i] 是长度 i+1 的递增子序列的最小尾值
    tails[left] = x;
  }
  return tails.length;
}

from bisect import bisect_left

def lengthOfLIS(nums: list[int]) -> int:
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

function maxProduct(nums: number[]): number {
  let high = nums[0], low = nums[0], best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const x = nums[i], a = high * x, b = low * x;
    high = Math.max(x, a, b);
    low = Math.min(x, a, b);
    best = Math.max(best, high);
  }
  return best;
}

function canPartition(nums: number[]): boolean {
  const sum = nums.reduce((a, b) => a + b, 0);
  if (sum % 2) return false;
  const target = sum / 2, dp = Array(target + 1).fill(false); dp[0] = true;
  for (const x of nums) {
    // 倒序更新保证每个数字只使用一次
    for (let value = target; value >= x; value--) dp[value] ||= dp[value - x];
  }
  return dp[target];
}

def canPartition(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    dp = [True] + [False] * target
    for x in nums:
        for value in range(target, x - 1, -1):
            dp[value] = dp[value] or dp[value - x]
    return dp[target]

function longestValidParentheses(s: string): number {
  const stack: number[] = [-1];
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "(") stack.push(i);
    else {
      stack.pop();
      if (!stack.length) stack.push(i);
      else best = Math.max(best, i - stack[stack.length - 1]);
    }
  }
  return best;
}

def longestValidParentheses(s: str) -> int:
    stack, best = [-1], 0
    for i, ch in enumerate(s):
        if ch == "(":
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

function uniquePaths(m: number, n: number): number {
  const dp = Array(n).fill(1);
  for (let row = 1; row < m; row++) {
    for (let col = 1; col < n; col++) dp[col] += dp[col - 1];
  }
  return dp[n - 1];
}

def uniquePaths(m: int, n: int) -> int:
    dp = [1] * n
    for _ in range(1, m):
        for col in range(1, n):
            dp[col] += dp[col - 1]
    return dp[-1]

function minPathSum(grid: number[][]): number {
  const dp = Array(grid[0].length).fill(Infinity); dp[0] = 0;
  for (const row of grid) {
    for (let col = 0; col < row.length; col++) {
      dp[col] = row[col] + Math.min(dp[col], col ? dp[col - 1] : Infinity);
    }
  }
  return dp[dp.length - 1];
}

def minPathSum(grid: list[list[int]]) -> int:
    dp = [float("inf")] * len(grid[0])
    dp[0] = 0
    for row in grid:
        for col, value in enumerate(row):
            dp[col] = value + min(dp[col], dp[col - 1] if col else float("inf"))
    return dp[-1]

function longestPalindrome(s: string): string {
  let start = 0, length = 0;
  const expand = (left: number, right: number): void => {
    while (left >= 0 && right < s.length && s[left] === s[right]) { left--; right++; }
    if (right - left - 1 > length) { start = left + 1; length = right - left - 1; }
  };
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i + 1); }
  return s.slice(start, start + length);
}

def longestPalindrome(s: str) -> str:
    start = length = 0
    def expand(left, right):
        nonlocal start, length
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left, right = left - 1, right + 1
        if right - left - 1 > length:
            start, length = left + 1, right - left - 1
    for i in range(len(s)):
        expand(i, i)
        expand(i, i + 1)
    return s[start:start + length]

function longestCommonSubsequence(a: string, b: string): number {
  const dp = Array(b.length + 1).fill(0);
  for (const ch of a) {
    let diagonal = 0;
    for (let j = 1; j <= b.length; j++) {
      const above = dp[j];
      dp[j] = ch === b[j - 1] ? diagonal + 1 : Math.max(dp[j], dp[j - 1]);
      diagonal = above;
    }
  }
  return dp[b.length];
}

def longestCommonSubsequence(a: str, b: str) -> int:
    dp = [0] * (len(b) + 1)
    for ch in a:
        diagonal = 0
        for j in range(1, len(b) + 1):
            above = dp[j]
            dp[j] = diagonal + 1 if ch == b[j - 1] else max(dp[j], dp[j - 1])
            diagonal = above
    return dp[-1]

function minDistance(word1: string, word2: string): number {
  const dp = Array.from({ length: word2.length + 1 }, (_, j) => j);
  for (let i = 1; i <= word1.length; i++) {
    let diagonal = dp[0]; dp[0] = i;
    for (let j = 1; j <= word2.length; j++) {
      const above = dp[j];
      dp[j] = word1[i - 1] === word2[j - 1] ? diagonal : 1 + Math.min(diagonal, above, dp[j - 1]);
      diagonal = above;
    }
  }
  return dp[word2.length];
}

def minDistance(word1: str, word2: str) -> int:
    dp = list(range(len(word2) + 1))
    for i, ch in enumerate(word1, 1):
        diagonal, dp[0] = dp[0], i
        for j in range(1, len(word2) + 1):
            above = dp[j]
            dp[j] = diagonal if ch == word2[j - 1] else 1 + min(diagonal, above, dp[j - 1])
            diagonal = above
    return dp[-1]

function singleNumber(nums: number[]): number {
  let result = 0;
  // 相同数异或为零，留下只出现一次的数
  for (const x of nums) result ^= x;
  return result;
}

def singleNumber(nums: list[int]) -> int:
