function majorityElement(nums: number[]): number {
  let candidate = 0, votes = 0;
  for (const x of nums) {
    if (votes === 0) candidate = x;
    // 不同元素两两抵消，多数元素必然幸存
    votes += x === candidate ? 1 : -1;
  }
  return candidate;
}

def majorityElement(nums: list[int]) -> int:
    candidate = votes = 0
    for x in nums:
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

function sortColors(nums: number[]): void {
  let left = 0, cur = 0, right = nums.length - 1;
  while (cur <= right) {
    if (nums[cur] === 0) { [nums[left], nums[cur]] = [nums[cur], nums[left]]; left++; cur++; }
    else if (nums[cur] === 2) {
      [nums[cur], nums[right]] = [nums[right], nums[cur]]; right--;
      // 换来的元素尚未检查，cur 保持不动
    } else cur++;
  }
}

def sortColors(nums: list[int]) -> None:
    left, cur, right = 0, 0, len(nums) - 1
    while cur <= right:
        if nums[cur] == 0:
            nums[left], nums[cur] = nums[cur], nums[left]
            left, cur = left + 1, cur + 1
        elif nums[cur] == 2:
            nums[cur], nums[right] = nums[right], nums[cur]
            right -= 1
        else:
            cur += 1

function nextPermutation(nums: number[]): void {
  let pivot = nums.length - 2;
  while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) pivot--;
  if (pivot >= 0) {
    let next = nums.length - 1;
    while (nums[next] <= nums[pivot]) next--;
    [nums[pivot], nums[next]] = [nums[next], nums[pivot]];
  }
  // 后缀原本递减，翻转后成为最小可用后缀
  let left = pivot + 1, right = nums.length - 1;
  while (left < right) { [nums[left], nums[right]] = [nums[right], nums[left]]; left++; right--; }
}

def nextPermutation(nums: list[int]) -> None:
    pivot = len(nums) - 2
    while pivot >= 0 and nums[pivot] >= nums[pivot + 1]:
        pivot -= 1
    if pivot >= 0:
        nxt = len(nums) - 1
        while nums[nxt] <= nums[pivot]:
            nxt -= 1
        nums[pivot], nums[nxt] = nums[nxt], nums[pivot]
    left, right = pivot + 1, len(nums) - 1
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left, right = left + 1, right - 1

function findDuplicate(nums: number[]): number {
  let slow = 0, fast = 0;
  // 将下标到数值的映射看作带环链表
  do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow !== fast);
  let entry = 0;
  while (entry !== slow) { entry = nums[entry]; slow = nums[slow]; }
  return entry;
}

def findDuplicate(nums: list[int]) -> int:
    slow = fast = 0
    while True:
        slow, fast = nums[slow], nums[nums[fast]]
        if slow == fast:
            break
    entry = 0
    while entry != slow:
        entry, slow = nums[entry], nums[slow]
    return entry
